"use client";

import Link from "next/link";
import Navbar from "../../components/Home/Nevbar";
import UnemployedDasbard from "../../components/unemployeed/unemployeedasboard";
import UnemployeeForm from "../../components/unemployeed/unemployeeform";
export default function UnemployedPage() {
  return (
    <div className="min-h-screen bg-[#E6F7F1] font-sans">
      {/* Navbar */}
      <Navbar />

      {/* Main two-column layout: dashboard (left) + form (right) */}
      <main className="max-w-6xl mx-auto mt-8 p-6 grid grid-cols-1 md:grid-cols-2 gap-8 items-start">
        <div className="col-span-1">
          <UnemployedDasbard />
        </div>

        <div className="col-span-1">
          <UnemployeeForm />
        </div>
      </main>
    
    
      {/* Footer */}
      <footer className="mt-12 p-6 text-center text-[#065F46]">
        &copy; {new Date().getFullYear()} Healthcare Support. All rights reserved.
      </footer>
    </div>
  );
}
